annotation { "Feature Type Name" : "ARV-1 CAR_MASTER sketches" }
export const arvCarMasterSketches = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        const O = vector(0, 0, 0) * millimeter;
        const TOP = plane(O, vector(0, 0, 1), vector(1, 0, 0));          // plan view (X, Y)
        const SIDE = plane(O, vector(0, -1, 0), vector(1, 0, 0));        // side view (X, Z)
        const L = V(context, "wheelbase");
        const TF = V(context, "frontTrack");
        const TR = V(context, "rearTrack");
        const D = V(context, "wheelDiameter");
        const W = V(context, "wheelWidth");
        const ZA = V(context, "axleHeight");
        const XF = V(context, "xFrontAxle");
        const XR = V(context, "xRearAxle");
        const FRONT = plane(vector(XF, 0 * millimeter, 0 * millimeter), vector(1, 0, 0), vector(0, 1, 0)); // (Y, Z) at front axle
        const REARARM = plane(vector(0 * millimeter, V(context, "rearArmY"), 0 * millimeter), vector(0, -1, 0), vector(1, 0, 0));
        const STEER = plane(vector(0 * millimeter, 0 * millimeter, V(context, "steeringArmZ")), vector(0, 0, 1), vector(1, 0, 0));

        // ---------------- SK00_GLOBAL_DATUMS
        var sk = newSketchOnPlane(context, id + "SK00_GLOBAL_DATUMS", { "sketchPlane" : TOP });
        skPoint(sk, "origin", { "position" : pXY(0 * millimeter, 0 * millimeter) });
        skLineSegment(sk, "centreline", { "start" : pXY(-V(context, "overallLength") / 2, 0 * millimeter), "end" : pXY(V(context, "overallLength") / 2, 0 * millimeter), "construction" : true });
        for (var s in [1, -1])
        {
            skPoint(sk, "wcF" ~ s, { "position" : pXY(XF, s * TF / 2) });
            skPoint(sk, "wcR" ~ s, { "position" : pXY(XR, s * TR / 2) });
        }
        skSolve(sk);

        // ---------------- SK01_VEHICLE_PLAN_ENVELOPE
        sk = newSketchOnPlane(context, id + "SK01_VEHICLE_PLAN_ENVELOPE", { "sketchPlane" : TOP });
        skRectangle(sk, "overall", { "firstCorner" : pXY(V(context, "rearBumperX"), -V(context, "overallWidth") / 2), "secondCorner" : pXY(V(context, "frontBumperX"), V(context, "overallWidth") / 2) });
        skRectangle(sk, "tub", { "firstCorner" : pXY(V(context, "chassisXmin"), -V(context, "chassisWidth") / 2), "secondCorner" : pXY(V(context, "chassisXmax"), V(context, "chassisWidth") / 2) });
        skRectangle(sk, "deck", { "firstCorner" : pXY(V(context, "deckXmin"), -V(context, "deckWidth") / 2), "secondCorner" : pXY(V(context, "deckXmin") + V(context, "deckLength"), V(context, "deckWidth") / 2) });
        for (var s in [1, -1])
        {
            skLineSegment(sk, "rail" ~ s, { "start" : pXY(V(context, "railXmin"), s * V(context, "railY")), "end" : pXY(V(context, "railXmax"), s * V(context, "railY")) });
        }
        skSolve(sk);

        // ---------------- SK02_VEHICLE_SIDE_ENVELOPE
        sk = newSketchOnPlane(context, id + "SK02_VEHICLE_SIDE_ENVELOPE", { "sketchPlane" : SIDE });
        skLineSegment(sk, "ground", { "start" : pXY(-V(context, "overallLength") / 2, 0 * millimeter), "end" : pXY(V(context, "overallLength") / 2, 0 * millimeter) });
        skCircle(sk, "wheelF", { "center" : pXY(XF, ZA), "radius" : D / 2 });
        skCircle(sk, "wheelR", { "center" : pXY(XR, ZA), "radius" : D / 2 });
        skRectangle(sk, "tub", { "firstCorner" : pXY(V(context, "chassisXmin"), V(context, "floorZ")), "secondCorner" : pXY(V(context, "chassisXmax"), V(context, "tubTopZ")) });
        skRectangle(sk, "deck", { "firstCorner" : pXY(V(context, "deckXmin"), V(context, "electronicsDeckHeight")), "secondCorner" : pXY(V(context, "deckXmin") + V(context, "deckLength"), V(context, "electronicsDeckHeight") + V(context, "deckThickness")) });
        skLineSegment(sk, "lidarPlane", { "start" : pXY(V(context, "lidarX") - 60 * millimeter, V(context, "lidarScanZ")), "end" : pXY(V(context, "lidarX") + 60 * millimeter, V(context, "lidarScanZ")), "construction" : true });
        skLineSegment(sk, "maxHeight", { "start" : pXY(-V(context, "overallLength") / 2, V(context, "overallHeightLidar")), "end" : pXY(V(context, "overallLength") / 2, V(context, "overallHeightLidar")), "construction" : true });
        skSolve(sk);

        // ---------------- SK03_WHEELBASE_AND_TRACK
        sk = newSketchOnPlane(context, id + "SK03_WHEELBASE_AND_TRACK", { "sketchPlane" : TOP });
        skLineSegment(sk, "frontAxle", { "start" : pXY(XF, -TF / 2), "end" : pXY(XF, TF / 2) });
        skLineSegment(sk, "rearAxle", { "start" : pXY(XR, -TR / 2), "end" : pXY(XR, TR / 2) });
        for (var s in [1, -1])
        {
            skRectangle(sk, "tyreF" ~ s, { "firstCorner" : pXY(XF - D / 2, s * TF / 2 - W / 2), "secondCorner" : pXY(XF + D / 2, s * TF / 2 + W / 2) });
            skRectangle(sk, "tyreR" ~ s, { "firstCorner" : pXY(XR - D / 2, s * TR / 2 - W / 2), "secondCorner" : pXY(XR + D / 2, s * TR / 2 + W / 2) });
        }
        skSolve(sk);

        // ---------------- SK04_FRONT_SUSPENSION_GEOMETRY  (front view at X = xFrontAxle; left side, mirror for right)
        sk = newSketchOnPlane(context, id + "SK04_FRONT_SUSPENSION_GEOMETRY", { "sketchPlane" : FRONT });
        const KY = V(context, "kingpinY");
        skLineSegment(sk, "lowerArm", { "start" : pXY(V(context, "frontLowerInnerY"), V(context, "frontLowerInnerZ")), "end" : pXY(KY, V(context, "kingpinLowerZ")) });
        skLineSegment(sk, "camberLink", { "start" : pXY(V(context, "frontUpperInnerY"), V(context, "frontUpperInnerZ")), "end" : pXY(KY, V(context, "kingpinUpperZ")) });
        skLineSegment(sk, "kingpin", { "start" : pXY(KY, V(context, "kingpinLowerZ")), "end" : pXY(KY, V(context, "kingpinUpperZ")) });
        skLineSegment(sk, "shockF", { "start" : pXY(V(context, "frontShockLowerY"), V(context, "frontShockLowerZ")), "end" : pXY(V(context, "frontShockUpperY"), V(context, "frontShockUpperZ")) });
        skLineSegment(sk, "spindle", { "start" : pXY(KY, ZA), "end" : pXY(TF / 2, ZA) });
        skCircle(sk, "hub", { "center" : pXY(TF / 2, ZA), "radius" : 1 * millimeter });
        skRectangle(sk, "tyre", { "firstCorner" : pXY(TF / 2 - W / 2, 0 * millimeter), "secondCorner" : pXY(TF / 2 + W / 2, D) });
        skSolve(sk);

        // ---------------- SK05_REAR_SUSPENSION_GEOMETRY  (side view in the arm plane)
        sk = newSketchOnPlane(context, id + "SK05_REAR_SUSPENSION_GEOMETRY", { "sketchPlane" : REARARM });
        skLineSegment(sk, "trailingArm", { "start" : pXY(V(context, "rearArmPivotX"), V(context, "rearArmPivotZ")), "end" : pXY(XR, ZA) });
        skCircle(sk, "pivot", { "center" : pXY(V(context, "rearArmPivotX"), V(context, "rearArmPivotZ")), "radius" : 2.5 * millimeter });
        skLineSegment(sk, "shockR", { "start" : pXY(V(context, "rearShockLowerX"), V(context, "rearShockLowerZ")), "end" : pXY(V(context, "rearShockUpperX"), V(context, "rearShockUpperZ")) });
        skCircle(sk, "motor", { "center" : pXY(XR, ZA), "radius" : 18.5 * millimeter });
        skSolve(sk);

        // ---------------- SK06_STEERING_GEOMETRY  (plan at steering-arm height)
        sk = newSketchOnPlane(context, id + "SK06_STEERING_GEOMETRY", { "sketchPlane" : STEER });
        const armL = V(context, "steeringArmLength");
        const armA = V(context, "steeringArmAngle");
        const cX = V(context, "crankPivotX");
        const cY = V(context, "crankPivotY");
        const cR = V(context, "crankRadius");
        const cB = V(context, "crankBeta");
        const dR = V(context, "crankDragRadius");
        for (var s in [1, -1])
        {
            const kp = pXY(XF + (ZA - V(context, "steeringArmZ")) * tan(V(context, "casterAngle")), s * KY);
            const tip = kp + pXY(armL * cos(armA), s * armL * sin(armA));
            const cp = pXY(cX, s * cY);
            const cb = cp + pXY(cR * cos(cB), s * cR * sin(cB));
            skLineSegment(sk, "arm" ~ s, { "start" : kp, "end" : tip });
            skLineSegment(sk, "tieRod" ~ s, { "start" : tip, "end" : cb });
            skLineSegment(sk, "crankTie" ~ s, { "start" : cp, "end" : cb });
            skLineSegment(sk, "crankDrag" ~ s, { "start" : cp, "end" : cp - pXY(dR, 0 * millimeter) });
            skLineSegment(sk, "ackermannRay" ~ s, { "start" : kp, "end" : pXY(XR, 0 * millimeter), "construction" : true });
        }
        skLineSegment(sk, "dragLink", { "start" : pXY(cX - dR, cY), "end" : pXY(cX - dR, -cY) });
        skLineSegment(sk, "servoHorn", { "start" : pXY(V(context, "servoX"), 0 * millimeter), "end" : pXY(V(context, "servoX") - V(context, "servoHornRadius"), 0 * millimeter) });
        skLineSegment(sk, "servoLink", { "start" : pXY(V(context, "servoX") - V(context, "servoHornRadius"), 0 * millimeter), "end" : pXY(cX - dR, 0 * millimeter) });
        skSolve(sk);

        // ---------------- SK07_DRIVETRAIN_LAYOUT  (plan)
        sk = newSketchOnPlane(context, id + "SK07_DRIVETRAIN_LAYOUT", { "sketchPlane" : TOP });
        for (var s in [1, -1])
        {
            skRectangle(sk, "motor" ~ s, { "firstCorner" : pXY(XR - 18.5 * millimeter, s * (V(context, "motorFaceY") - 82 * millimeter)), "secondCorner" : pXY(XR + 18.5 * millimeter, s * V(context, "motorFaceY")) });
            skLineSegment(sk, "shaft" ~ s, { "start" : pXY(XR, s * V(context, "motorFaceY")), "end" : pXY(XR, s * TR / 2) });
        }
        skSolve(sk);

        // ---------------- SK08_BATTERY_ENVELOPE  (plan)
        sk = newSketchOnPlane(context, id + "SK08_BATTERY_ENVELOPE", { "sketchPlane" : TOP });
        const bx = V(context, "batteryX");
        const bw = V(context, "batteryWidth") / 2 + V(context, "batteryClearance");
        skRectangle(sk, "tunnel", { "firstCorner" : pXY(bx - bw, -V(context, "chassisWidth") / 2), "secondCorner" : pXY(bx + bw, V(context, "chassisWidth") / 2) });
        skRectangle(sk, "battery", { "firstCorner" : pXY(bx - V(context, "batteryWidth") / 2, -V(context, "batteryLength") / 2), "secondCorner" : pXY(bx + V(context, "batteryWidth") / 2, V(context, "batteryLength") / 2) });
        skSolve(sk);

        // ---------------- SK09_COMPUTE_AND_ELECTRONICS  (plan; lower bay + deck zones)
        sk = newSketchOnPlane(context, id + "SK09_COMPUTE_AND_ELECTRONICS", { "sketchPlane" : TOP });
        skRectangle(sk, "jetson", { "firstCorner" : pXY(-65.5 * millimeter, -45.25 * millimeter), "secondCorner" : pXY(37.5 * millimeter, 45.25 * millimeter) });
        skRectangle(sk, "motorDriver", { "firstCorner" : pXY(-104 * millimeter, 1 * millimeter), "secondCorner" : pXY(-20 * millimeter, 63 * millimeter) });
        skRectangle(sk, "dcdc19", { "firstCorner" : pXY(-102 * millimeter, -62 * millimeter), "secondCorner" : pXY(-42 * millimeter, -12 * millimeter) });
        skRectangle(sk, "fuseBlock", { "firstCorner" : pXY(64 * millimeter, 8 * millimeter), "secondCorner" : pXY(104 * millimeter, 63 * millimeter) });
        skRectangle(sk, "servoBec", { "firstCorner" : pXY(64 * millimeter, -40 * millimeter), "secondCorner" : pXY(104 * millimeter, -15 * millimeter) });
        skRectangle(sk, "mcu", { "firstCorner" : pXY(57 * millimeter, 17 * millimeter), "secondCorner" : pXY(127 * millimeter, 67 * millimeter) });
        skCircle(sk, "imu", { "center" : pXY(115 * millimeter, -46 * millimeter), "radius" : 12 * millimeter });
        skSolve(sk);

        // ---------------- SK10_SENSOR_LAYOUT  (side: optical axes and FOV bounds)
        sk = newSketchOnPlane(context, id + "SK10_SENSOR_LAYOUT", { "sketchPlane" : SIDE });
        const cz = V(context, "cameraZ");
        const cx = V(context, "cameraX");
        const ct = V(context, "cameraTilt");
        skLineSegment(sk, "camAxis", { "start" : pXY(cx, cz), "end" : pXY(cx + 400 * millimeter * cos(ct), cz - 400 * millimeter * sin(ct)), "construction" : true });
        const dx = V(context, "depthX");
        const dz = V(context, "depthZ");
        const dt = V(context, "depthTilt");
        skLineSegment(sk, "depthUpper", { "start" : pXY(dx, dz), "end" : pXY(dx + 400 * millimeter * cos(29 * degree - dt), dz + 400 * millimeter * sin(29 * degree - dt)), "construction" : true });
        skLineSegment(sk, "depthLower", { "start" : pXY(dx, dz), "end" : pXY(dx + 400 * millimeter * cos(29 * degree + dt), dz - 400 * millimeter * sin(29 * degree + dt)), "construction" : true });
        skLineSegment(sk, "lidarScan", { "start" : pXY(-V(context, "overallLength") / 2, V(context, "lidarScanZ")), "end" : pXY(V(context, "overallLength") / 2, V(context, "lidarScanZ")), "construction" : true });
        skPoint(sk, "imu", { "position" : pXY(V(context, "imuX"), V(context, "electronicsDeckHeight") + 15 * millimeter) });
        skLineSegment(sk, "tofAxis", { "start" : pXY(V(context, "frontBumperX"), V(context, "tofZ")), "end" : pXY(V(context, "frontBumperX") + 300 * millimeter, V(context, "tofZ")), "construction" : true });
        skSolve(sk);

        // ---------------- SK11_BODY_AND_PROTECTION  (plan)
        sk = newSketchOnPlane(context, id + "SK11_BODY_AND_PROTECTION", { "sketchPlane" : TOP });
        skRectangle(sk, "frontBumper", { "firstCorner" : pXY(222 * millimeter, -V(context, "bumperWidth") / 2 - 15 * millimeter), "secondCorner" : pXY(V(context, "frontBumperX"), V(context, "bumperWidth") / 2 + 15 * millimeter) });
        skRectangle(sk, "rearBumper", { "firstCorner" : pXY(V(context, "rearBumperX"), -V(context, "bumperWidth") / 2 - 15 * millimeter), "secondCorner" : pXY(-226 * millimeter, V(context, "bumperWidth") / 2 + 15 * millimeter) });
        skSolve(sk);

        // ---------------- SK12_CABLE_ROUTING  (plan: power on the right (-Y), signal on the left (+Y))
        sk = newSketchOnPlane(context, id + "SK12_CABLE_ROUTING", { "sketchPlane" : TOP });
        skLineSegment(sk, "pwr1", { "start" : pXY(-8 * millimeter, 70 * millimeter), "end" : pXY(-8 * millimeter, -30 * millimeter) });
        skLineSegment(sk, "pwr2", { "start" : pXY(-8 * millimeter, -30 * millimeter), "end" : pXY(84 * millimeter, -30 * millimeter) });
        skLineSegment(sk, "pwr3", { "start" : pXY(-62 * millimeter, -50 * millimeter), "end" : pXY(-62 * millimeter, -30 * millimeter) });
        skLineSegment(sk, "sig1", { "start" : pXY(-62 * millimeter, 50 * millimeter), "end" : pXY(92 * millimeter, 50 * millimeter) });
        skLineSegment(sk, "sig2", { "start" : pXY(92 * millimeter, 50 * millimeter), "end" : pXY(150 * millimeter, 0 * millimeter) });
        skLineSegment(sk, "sensorTrunk", { "start" : pXY(118 * millimeter, 0 * millimeter), "end" : pXY(160 * millimeter, 0 * millimeter) });
        skSolve(sk);

        // ---------------- SK13_MOUNTING_INTERFACE_STANDARD  (20 mm M3 insert grid on the deck)
        sk = newSketchOnPlane(context, id + "SK13_MOUNTING_INTERFACE_STANDARD", { "sketchPlane" : plane(vector(0 * millimeter, 0 * millimeter, V(context, "electronicsDeckHeight") + V(context, "deckThickness")), vector(0, 0, 1), vector(1, 0, 0)) });
        const gp = V(context, "gridPitch");
        const gx0 = V(context, "deckXmin") + V(context, "deckLength") / 2;
        for (var i = -4; i <= 5; i += 1)
        {
            for (var j = -3; j <= 4; j += 1)
            {
                skPoint(sk, "g" ~ (i + 10) ~ "_" ~ (j + 10), { "position" : pXY(gx0 + (i - 0.5) * gp, (j - 0.5) * gp) });
            }
        }
        skSolve(sk);

        // ---------------- SK14_GROUND_CLEARANCE_AND_TRAVEL  (front view: bump / ride / droop wheel outlines)
        sk = newSketchOnPlane(context, id + "SK14_GROUND_CLEARANCE_AND_TRAVEL", { "sketchPlane" : FRONT });
        skLineSegment(sk, "ground", { "start" : pXY(-V(context, "overallWidth") / 2, 0 * millimeter), "end" : pXY(V(context, "overallWidth") / 2, 0 * millimeter) });
        skLineSegment(sk, "skid", { "start" : pXY(-V(context, "chassisWidth") / 2, V(context, "groundClearance")), "end" : pXY(V(context, "chassisWidth") / 2, V(context, "groundClearance")) });
        for (var t in [-1, 0, 1])
        {
            const tz = t == 1 ? V(context, "bumpTravel") : (t == -1 ? -V(context, "droopTravel") : 0 * millimeter);
            skRectangle(sk, "tyre" ~ (t + 1), { "firstCorner" : pXY(TF / 2 - W / 2, tz), "secondCorner" : pXY(TF / 2 + W / 2, tz + D) });
        }
        skSolve(sk);
    });
